/* Final visual QA layer: single global stylesheet, no inline overrides. */
/* Login: reserve a stable gutter for the leading icon. */
body[data-intranet-page="index"] #loginForm .input-wrapper > .input-icon {
  left: 14px !important;
  width: 18px;
  z-index: 2;
  pointer-events: none;
}
body[data-intranet-page="index"] #loginForm .input-wrapper > #loginEmail,
body[data-intranet-page="index"] #loginForm .input-wrapper > #loginSenha {
  box-sizing: border-box;
  padding-left: 44px !important;
  text-indent: 0 !important;
}

/* Atas: one clean surface behind the crest; no white background on the PNG itself. */
body[data-intranet-module="atas"] .sidebar-brand .brand-icon,
body[data-intranet-module="atas"] #mainSystem .sidebar-brand .brand-icon {
  box-sizing: border-box !important;
  width: 44px !important;
  height: 44px !important;
  min-width: 44px !important;
  min-height: 44px !important;
  max-height: 44px !important;
  flex: 0 0 44px !important;
  display: grid !important;
  place-items: center !important;
  padding: 3px !important;
  overflow: hidden !important;
  background: #fff !important;
  border: 1px solid rgba(255, 255, 255, .72) !important;
  border-radius: 12px !important;
  box-shadow: 0 4px 12px rgba(0, 0, 0, .14) !important;
}
body[data-intranet-module="atas"] .sidebar-brand .brand-icon img.brasao-municipio,
body[data-intranet-module="atas"] #mainSystem .sidebar-brand .brand-icon img.brasao-municipio {
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  padding: 0 !important;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  object-fit: contain !important;
}

/* Atas dashboard: stop flex children/sparklines from squeezing KPI values. */
body[data-intranet-page="controle-de-saldos-gestao-atas"] .dashboard-kpis {
  grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
}
body[data-intranet-page="controle-de-saldos-gestao-atas"] .kpi-card {
  min-width: 0 !important;
}
body[data-intranet-page="controle-de-saldos-gestao-atas"] .kpi-content {
  flex: 1 1 auto !important;
  min-width: 0 !important;
}
body[data-intranet-page="controle-de-saldos-gestao-atas"] .kpi-sparkline {
  display: flex !important;
}
body[data-intranet-page="controle-de-saldos-gestao-atas"] .kpi-valor {
  white-space: nowrap !important;
  word-break: normal !important;
  overflow-wrap: normal !important;
  font-size: clamp(.92rem, 1.15vw, 1.12rem) !important;
}
@media screen and (max-width: 1500px) {
  body[data-intranet-page="controle-de-saldos-gestao-atas"] .dashboard-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }
  body[data-intranet-page="controle-de-saldos-gestao-atas"] .kpi-sparkline {
    display: none !important;
  }
}
@media screen and (max-width: 680px) {
  body[data-intranet-page="controle-de-saldos-gestao-atas"] .dashboard-kpis {
    grid-template-columns: minmax(0, 1fr) !important;
  }
  body[data-intranet-page="controle-de-saldos-gestao-atas"] .kpi-card {
    padding: 14px 16px !important;
  }
  body[data-intranet-page="controle-de-saldos-gestao-atas"] .kpi-valor {
    font-size: 1rem !important;
  }
}

/* Reusable institutional heading for screen-based reports and print. */
.municipal-report-print-header {
  display: none;
}
.municipal-report-heading {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 0 16px;
  padding: 12px 14px;
  border: 1px solid #d9e2ec;
  border-radius: 12px;
  background: #f7fafc;
}
.municipal-report-heading .municipal-report-crest {
  display: block;
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  object-fit: contain;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}
.municipal-report-heading strong,
.municipal-report-print-header strong {
  display: block;
  color: #12304a;
  font-size: 1rem;
  font-weight: 800;
}
.municipal-report-heading h3,
.municipal-report-print-header span {
  display: block;
  margin: 3px 0 0;
  color: #455b70;
  font-size: .9rem;
  font-weight: 600;
}
.municipal-report-content .saldo-divergencia-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 10px;
  border-radius: 20px;
  font-weight: 600;
}
.municipal-report-content .saldo-divergencia-badge--positiva {
  background: var(--success-100);
  color: var(--success-800);
}
.municipal-report-content .saldo-divergencia-badge--negativa {
  background: var(--error-100);
  color: var(--error-800);
}
.municipal-report-print-header img {
  display: block;
  width: 18mm;
  height: 18mm;
